function regionColor(region: LogRegion): (text: string) => string {
  switch (region) {
    case 'root':
      return (t) => chalk.bold(t);
    case 'ancestor':
      return (t) => chalk.cyan(t);
    case 'sibling-subtree':
      return (t) => chalk.dim(t);
    case 'current':
    case 'descendant':
      return (t) => t;
  }
}

